                { stageId: "calc-s6b", topic: "Derivative Interpretations", module: "Practice", component: "PatternMatcher", skin: "Code", config: { data: { pairs: [{ id: "p1", left: "f'(a)", right: "Slope of tangent line at x=a" }, { id: "p2", left: "f'(a) > 0", right: "Function is increasing at x=a" }, { id: "p3", left: "f'(a) = 0", right: "Possible max/min or inflection" }, { id: "p4", left: "f'(a) < 0", right: "Function is decreasing at x=a" }] }, initialState: {} }, validation: { type: "exact", condition: {} }, feedback: { success: "Derivative interpretations matched!", error: "The sign of f' tells you the direction of the function.", hint: "Positive slope = going up; negative slope = going down." } },
                { stageId: "calc-s6c", topic: "Computing from Definition", module: "Practice", component: "LogicChain", skin: "Code", config: { data: { nodes: ["f(x) = x², find f'(x) from definition", "f'(x) = lim(h→0) [(x+h)² - x²] / h", "= lim(h→0) [x² + 2xh + h² - x²] / h", "= lim(h→0) [2xh + h²] / h", "= lim(h→0) (2x + h) = 2x"] }, initialState: {} }, validation: { type: "exact", condition: {} }, feedback: { success: "Derivative from first principles!", error: "Expand (x+h)², subtract x², simplify, then take limit.", hint: "(x+h)² = x² + 2xh + h²." } },
                { stageId: "calc-s6d", topic: "Secant to Tangent", module: "Practice", component: "TaxonomyMatrix", skin: "Code", config: { data: { buckets: ["Secant line", "Tangent line"], items: [{ id: "dt1", content: "Passes through two points" }, { id: "dt2", content: "Touches curve at one point" }, { id: "dt3", content: "Average rate of change" }, { id: "dt4", content: "Instantaneous rate of change" }, { id: "dt5", content: "Slope = [f(b)-f(a)]/(b-a)" }, { id: "dt6", content: "Slope = lim(h→0) [f(a+h)-f(a)]/h" }], correctAssignments: { "dt1": "Secant line", "dt2": "Tangent line", "dt3": "Secant line", "dt4": "Tangent line", "dt5": "Secant line", "dt6": "Tangent line" } }, initialState: {} }, validation: { type: "exact", condition: {} }, feedback: { success: "Secant vs tangent distinguished!", error: "As the two points merge, secant → tangent.", hint: "Secant = average slope over interval; tangent = slope at a point." } },
                { stageId: "calc-s6e", topic: "Differentiability", module: "Practice", component: "MultipleChoice", skin: "Code", config: { data: { question: "If f is differentiable at x=a, then f must be:", options: [{ id: "a", text: "Constant near a" }, { id: "b", text: "Continuous at a" }, { id: "c", text: "Increasing at a" }, { id: "d", text: "Positive at a" }], correctId: "b" }, initialState: {} }, validation: { type: "exact", condition: {} }, feedback: { success: "Correct! Differentiable → Continuous (but not vice versa).", error: "Differentiability is a stronger condition than continuity.", hint: "You need continuity to have a derivative, but |x| is continuous at 0 without being differentiable." } },
                { stageId: "calc-s6f", topic: "Teach: Derivative Concept", module: "Assessment", component: "FeynmanPrompt", skin: "Code", config: { data: { prompt: "Explain what a derivative represents using a real-world example involving speed and distance.", sampleAnswer: "If s(t) represents the distance traveled at time t, then the derivative s'(t) gives the instantaneous speed at time t. Imagine driving and watching your speedometer — the speedometer shows s'(t), the rate at which distance changes at that exact moment. The derivative is computed as the limit of average speed over shorter and shorter time intervals: lim(Δt→0) [s(t+Δt) - s(t)] / Δt.", fixedFeedback: "Excellent real-world connection! Distance → speed via derivative is the most intuitive example. Your speedometer analogy is perfect — it shows instantaneous rate of change. And connecting it back to the limit definition ties the intuition to the math. Great teaching!" }, initialState: {} }, validation: { type: "exact", condition: {} }, feedback: { success: "Great teaching!", error: "Think about how speed relates to distance over time.", hint: "Speed = rate of change of distance = derivative of position." } }
